import math
state={'psi':0.0,'last':-9,'fwd_until':-1,'mem':[]}

def clamp(v,a,b):
    return max(a,min(b,v))

def pts_from(obs):
    P=[]
    views=obs.get('views') or {}
    for k,v in views.items():
        if not v: continue
        o=v.get('origin',[0,0])
        for w in v.get('walls',[]) or []:
            b=math.radians(w[0]);d=w[1]
            P.append((o[0]+d*math.cos(b),o[1]+d*math.sin(b)))
    return P

def control(obs):
    t=obs['t']
    rig=obs['rig']
    h=rig['hitch'];r=rig['trailer_rear']
    ux=r[0]-h[0];uy=r[1]-h[1];n=math.hypot(ux,uy) or 1
    ux/=n;uy/=n
    au=math.atan2(uy,ux)
    px,py=uy,-ux
    gam=obs['hitch_deg']
    look=-23
    if abs(gam)>48 or t<state['fwd_until']:
        if t>=state['fwd_until']:
            state['fwd_until']=t+2.5
        return (0.0,1.0,look)
    P=pts_from(obs)
    if P:
        state['mem']=P
    P=state['mem']
    # free distance per direction
    best=[]
    for i in range(-12,13):
        psi=i*5
        a=au-math.radians(psi)
        dx,dy=math.cos(a),math.sin(a)
        f=8.0
        for (x,y) in P:
            rx=x-r[0];ry=y-r[1]
            al=rx*dx+ry*dy
            if al<=0: continue
            lat=abs(-rx*dy+ry*dx)
            if lat<1.1 and al<f: f=al
        best.append((psi,f))
    fmax=max(f for _,f in best)
    # run containing best closest to previous psi
    ok=[p for p,f in best if f>=fmax-0.3]
    cand=min(ok,key=lambda p:abs(p-state['psi']))
    lo=cand;hi=cand
    while lo-5 in ok: lo-=5
    while hi+5 in ok: hi+=5
    psi=(lo+hi)/2.0
    # centering
    dl=9;dr=9
    for (x,y) in P:
        rx=x-r[0];ry=y-r[1]
        al=rx*ux+ry*uy
        if -3.5<al<1.5:
            lat=rx*px+ry*py
            if lat>0: dl=min(dl,lat)
            else: dr=min(dr,-lat)
    if dl<9 and dr<9:
        psi+=clamp(8*(dl-dr),-15,15)
    elif dl<1.3: psi-=10*(1.3-dl)
    elif dr<1.3: psi+=10*(1.3-dr)
    state['psi']=0.7*state['psi']+0.3*psi
    gd=clamp(1.0*state['psi'],-35,35)
    steer=clamp(0.75*gd+2.0*(gam-gd),-34,34)
    if t-state['last']>=1.0:
        state['last']=t
        print('t%.1f g%.1f gd%.1f psi%.1f run%d..%d fmax%.1f dl%.2f dr%.2f st%.1f tgt%s'%(t,gam,gd,state['psi'],lo,hi,fmax,dl,dr,steer,obs.get('target')))
    return (steer,-0.9,look)

