import math
S={'ph':0,'psi':0.0,'s':0.0,'sr':0.0,'last':-9,'t0':None}
BAY=9.0
L=2.75
def cl(v,a,b):
    return max(a,min(b,v))
def control(obs):
    t=obs['t'];dt=obs.get('dt',0.1)
    v=obs['motion']['v_mps'];st=obs['steer_deg'];gam=obs['hitch_deg']
    S['psi']+=math.degrees(v*math.tan(math.radians(st))/L)*dt
    th=S['psi']-gam
    if t-S['last']>=1.0:
        S['last']=t
        print('t%.1f ph%d psi%.1f th%.1f g%.1f s%.2f sr%.2f rem%s'%(t,S['ph'],S['psi'],th,gam,S['s'],S['sr'],obs['progress'].get('remaining')))
    if S['ph']==0:
        S['s']+=max(v,0)*dt
        steer=cl(3.0*(BAY-S['psi']),-20,20)
        if S['s']>=3.0:
            S['ph']=1
            return (0.0,0.0,-23)
        return (steer,0.9,-23)
    if S['ph']==1:
        if abs(v)<0.02 and obs['motion'].get('hold_s',0)<=0 and abs(v)<0.02:
            S['ph']=2
        else:
            return (0.0,-0.6,-23)
    S['sr']+=max(-v,0)*dt
    if S['sr']>S['s']+0.4:
        return (0.0,0.0,-23)
    e=th-BAY
    gd=cl(1.5*e,-12,12)
    steer=cl(0.75*gd+2.0*(gam-gd),-34,34)
    return (steer,-0.6,-23)

