import math
L=2.5;LT=3.6
S={'x':0.0,'y':0.0,'th':0.0,'pts':{},'corn':[],'tc':None,'ph':'rev','ft':0.0,'al':0.0,'n':0,'gi':0,'gt':0.0,'stk':0.0,'mode':'gap'}
G=[(150,1.0),(64,0.6),(-64,0.6),(-150,1.0),(-64,0.6),(64,0.6)]
def cl(v,a,b):
    return max(a,min(b,v))
def wr(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def tw(px,py):
    c=math.cos(S['th']);s=math.sin(S['th'])
    return (S['x']+c*px-s*py,S['y']+s*px+c*py)
def addc(w):
    for c in S['corn']:
        if math.hypot(c[0]-w[0],c[1]-w[1])<1.0:
            n=c[2];c[0]=(c[0]*n+w[0])/(n+1);c[1]=(c[1]*n+w[1])/(n+1);c[2]=min(n+1,30);return
    S['corn'].append([w[0],w[1],1])
def choose(P,beta,near):
    best=-1e9;ba=0
    for a in range(-60,61,5):
        ang=beta+math.radians(a);ca=math.cos(ang);sa=math.sin(ang);sc=0.0
        for i in range(1,13):
            s=0.6*i;qx=P[0]+ca*s;qy=P[1]+sa*s
            c2=100.0
            for (x,y) in near:
                d=(qx-x)**2+(qy-y)**2
                if d<c2:c2=d
            c=math.sqrt(c2)
            if c<1.5:break
            sc+=min(c,2.2)
        sc-=0.02*abs(a)+0.01*abs(a-S['al'])
        if sc>best:best=sc;ba=a
    return ba
def control(obs):
    dt=obs.get('dt') or 0.1
    m=obs['motion'];v=m['v_mps'];sd=obs['steer_deg'];t=obs['t']
    S['th']+=v*math.tan(math.radians(sd))/L*dt
    S['x']+=v*math.cos(S['th'])*dt;S['y']+=v*math.sin(S['th'])*dt
    S['n']+=1
    vs=obs.get('views') or {}
    for k in vs:
        vw=vs[k]
        if not isinstance(vw,dict):continue
        o=vw.get('origin',[0.75,0])
        for p in vw.get('walls') or []:
            b=math.radians(p[0]);d=p[1]
            w=tw(o[0]+d*math.cos(b),o[1]+d*math.sin(b))
            S['pts'][(round(w[0]*3),round(w[1]*3))]=(w[0],w[1],t)
        for p in vw.get('target_corners') or []:
            try:
                b=math.radians(float(p[0]));d=float(p[1])
                addc(tw(o[0]+d*math.cos(b),o[1]+d*math.sin(b)))
            except Exception:
                pass
    rig=obs['rig']
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        e=rig['eye'];b=math.radians(tg['bearing_deg']);d=tg['dist_m']
        w=tw(e[0]+d*math.cos(b),e[1]+d*math.sin(b))
        if S['tc'] is None:S['tc']=list(w)
        else:
            S['tc'][0]+=0.2*(w[0]-S['tc'][0]);S['tc'][1]+=0.2*(w[1]-S['tc'][1])
