            S['gi']=(S['gi']+1)%len(G);S['gt']=0.0
    look=G[S['gi']][0]
    if S['n']%3==1:
        cs=sorted(S['corn'],key=lambda c:-c[2])[:4]
        aim=None;S['mode']='gap'
        if len(cs)==4:
            cx=sum(c[0] for c in cs)/4;cy=sum(c[1] for c in cs)/4
            if math.hypot(P[0]-cx,P[1]-cy)<12:
                sxx=sum((c[0]-cx)**2 for c in cs);syy=sum((c[1]-cy)**2 for c in cs);sxy=sum((c[0]-cx)*(c[1]-cy) for c in cs)
                ax=0.5*math.atan2(2*sxy,sxx-syy);ux=math.cos(ax);uy=math.sin(ax)
                if ux*math.cos(beta)+uy*math.sin(beta)<0:
                    ux=-ux;uy=-uy
                tp=(P[0]-cx)*ux+(P[1]-cy)*uy
                aim=(cx+ux*(tp+3.0),cy+uy*(tp+3.0));S['mode']='bay'
        if aim is None and S['tc'] is not None and math.hypot(P[0]-S['tc'][0],P[1]-S['tc'][1])<9:
            aim=(S['tc'][0],S['tc'][1]);S['mode']='tc'
        if aim is not None:
            S['al']=math.degrees(wr(math.atan2(aim[1]-P[1],aim[0]-P[0])-beta))
        else:
            near=[(q[0],q[1]) for q in S['pts'].values() if t-q[2]<40 and abs(q[0]-P[0])<10 and abs(q[1]-P[1])<10]
            S['al']=choose(P,beta,near)
    al=cl(S['al'],-60,60)
    sp=-1.0
    if S['tc'] is not None and math.hypot(P[0]-S['tc'][0],P[1]-S['tc'][1])<6:
        sp=-0.6
    if S['n']%30==0:
        print('t%.1f P(%.1f,%.1f) h%.0f al%.0f mode %s ph %s pts %d corn %d tc %s'%(t,P[0],P[1],h,al,S['mode'],S['ph'],len(S['pts']),len(S['corn']),S['tc']))
    if S['ph']=='rev' and abs(h)>45:
        S['ph']='fwd';S['ft']=0.0
    if S['ph']=='fwd':
        S['ft']+=dt
        if (abs(h)<8 and S['ft']>1.0) or S['ft']>6:
            S['ph']='rev';S['stk']=0.0
        return (cl(-1.5*h,-45,45),1.0,look)
    if m.get('hold_s',0)<=0 and abs(v)<0.05 and t>4:
        S['stk']+=dt
    else:
        S['stk']=0.0
    if S['stk']>2.5:
        S['stk']=0.0;S['ph']='fwd';S['ft']=0.0
        try:
            wake('stuck reversing, pulling forward')
        except Exception:
            pass
    vv=max(abs(v),0.5)
    x=cl(LT*0.35*math.radians(al)/vv,-1,1)
    pd=cl(-math.degrees(math.asin(x)),-30,30)
    steer=cl(3.0*(h-pd),-45,45)
    return (steer,sp,look)

