import math
L=2.5;LT=3.6
S={'x':0.0,'y':0.0,'th':0.0,'pts':{},'n':0,'pd':9.0,'gi':0,'gt':0.0,'stop':False,'al':0.0,'stk':0.0,'dbg':''}
G=[(150,0.8),(-64,0.5),(-150,0.8),(64,0.5),(-30,0.4)]
def cl(v,a,b):
    return max(a,min(b,v))
def W(px,py,x=None,y=None,th=None):
    if x is None:x=S['x'];y=S['y'];th=S['th']
    c=math.cos(th);s=math.sin(th)
    return (x+c*px-s*py,y+s*px+c*py)
def wk(m):
    try:
        wake(m)
    except Exception:
        pass
def md(pl,near):
    mn=9.0
    for (bx,by) in pl:
        for (qx,qy) in near:
            d=(bx-qx)**2+(by-qy)**2
            if d<mn*mn:mn=math.sqrt(d)
    return mn
def tbody(vf,hw,x,y,th):
    b=[W(vf,0.0,x,y,th)]
    for xx in (vf,vf-1.3,vf-2.6,vf-3.9):
        b.append(W(xx,hw,x,y,th));b.append(W(xx,-hw,x,y,th))
    return b
def control(obs):
    dt=obs.get('dt') or 0.1
    m=obs['motion'];v=m['v_mps'];sd=obs['steer_deg'];t=obs['t'];h=obs['hitch_deg']
    S['th']+=v*math.tan(math.radians(sd))/L*dt
    S['x']+=v*math.cos(S['th'])*dt;S['y']+=v*math.sin(S['th'])*dt
    S['n']+=1
    for k,vw in (obs.get('views') or {}).items():
        if not isinstance(vw,dict):continue
        o=vw.get('origin') or [0.75,0]
        for p in vw.get('walls') or []:
            if p[1]>10:continue
            b=math.radians(p[0]);w=W(o[0]+p[1]*math.cos(b),o[1]+p[1]*math.sin(b))
            S['pts'][(round(w[0]*3),round(w[1]*3))]=(w[0],w[1],t)
    if S['n']%50==0:
        S['pts']={k:q for k,q in S['pts'].items() if t-q[2]<30}
    hd_=obs['head']
    if hd_.get('settled'):
        S['gt']+=dt
        if S['gt']>G[S['gi']][1]:
            S['gi']=(S['gi']+1)%len(G);S['gt']=0.0
    look=G[S['gi']][0]
    rig=obs['rig'];Hv=rig['hitch'];Rv=rig['trailer_rear']
    Hw=W(Hv[0],Hv[1]);Rw=W(Rv[0],Rv[1])
    dx=Rw[0]-Hw[0];dy=Rw[1]-Hw[1];dn=math.hypot(dx,dy) or 1.0
    ux=dx/dn;uy=dy/dn
    vf=rig.get('vehicle_front',3.1)
    if isinstance(vf,(list,tuple)):vf=vf[0]
    try:vf=float(vf)
    except Exception:vf=3.1
    hw=rig.get('vehicle_half_width') or 1.15
    thw=rig.get('trailer_half_width') or 1.2
    nx=-uy;ny=ux
    tl=[];tr=[Rw]
    for s_ in (0.0,1.4,2.8,4.2):
        cx=Rw[0]-ux*s_;cy=Rw[1]-uy*s_
        tl.append((cx+nx*thw,cy+ny*thw));tr.append((cx-nx*thw,cy-ny*thw))
    near=[(q[0],q[1]) for q in S['pts'].values() if t-q[2]<20 and abs(q[0]-S['x'])<11 and abs(q[1]-S['y'])<11]
    vnear=[q for q in near if abs(q[0]-S['x'])<5.5 and abs(q[1]-S['y'])<5.5]
    tb=tbody(vf,hw,S['x'],S['y'],S['th'])
    dtr=md(tb,vnear);dl=md(tl,near);dr=md(tr,near)
    dmin=min(dtr,dl,dr)
    appr=dmin<S['pd']-0.003 and abs(v)>0.04
    S['pd']=dmin
    if (not S['stop']) and (dtr<0.12 or min(dl,dr)<0.16) and appr:
        S['stop']=True;wk('guard stop dtr%.2f dl%.2f dr%.2f h%.0f'%(dtr,dl,dr,h))
    if (not S['stop']) and (abs(h)>44 or obs.get('status')=='JACKKNIFED'):
        S['stop']=True;wk('hitch %.0f too big, stopped'%h)
    if S['stop']:
        return (sd,0.0,look)
    if S['n']%3==1:
        Lm=None;Rm=None
        for (qx,qy) in near:
            ex=qx-Rw[0];ey=qy-Rw[1];lo=ex*ux+ey*uy;la=ex*nx+ey*ny
            if 1.0<lo<7.0:
                if la>0:
                    if Lm is None or la<Lm:Lm=la
                else:
                    if Rm is None or la>Rm:Rm=la
        if Lm is not None and Rm is not None:c=(Lm+Rm)/2
        elif Lm is not None:c=Lm-2.5
        elif Rm is not None:c=Rm+2.5
        else:c=0.0
        c=cl(c,-3,3)
        na=math.degrees(math.atan2(c,4.5))
        na+=30*(max(0.0,0.7-dr)-max(0.0,0.7-dl))
        S['al']+=0.5*(cl(na,-35,35)-S['al'])
        S['dbg']='c%.1f L%s R%s'%(c,None if Lm is None else round(Lm,1),None if Rm is None else round(Rm,1))
    al=S['al']
    hd=math.degrees(math.asin(cl(-1.6*math.sin(math.radians(al)),-1,1)))
    hd=cl(hd,-30,30)
    steer=cl(3.0*(h-hd),-45,45)
    if dtr<0.45 and vnear:
        for cand in sorted(range(-45,46,9),key=lambda a:abs(a-steer)):
            ds=-0.35;dth=ds*math.tan(math.radians(cand))/L
            nt=S['th']+dth;hm=S['th']+dth/2
            c2=md(tbody(vf,hw,S['x']+ds*math.cos(hm),S['y']+ds*math.sin(hm),nt),vnear)
            if c2>=min(0.3,dtr+0.03):
                steer=cand;break
    sp=-0.45
    if dmin<0.4:sp=-0.3
    if m.get('hold_s',0)<=0 and abs(v)<0.03:
        S['stk']+=dt
    else:
        S['stk']=0.0
    if S['stk']>4.0:
        S['stk']=-30.0;wk('not moving in reverse')
    if S['n']%15==0:
        print('R t%.1f h%.0f al%.0f hd%.0f st%.0f dtr%.2f dl%.2f dr%.2f %s'%(t,h,al,hd,steer,dtr,dl,dr,S['dbg']))
    return (steer,sp,look)

