    return (S['x']+c*px-s*py, S['y']+s*px+c*py)
def mind(pts):
    best=9.0
    for (wx,wy) in S['mem'].values():
        for (px,py) in pts:
            dd=(wx-px)**2+(wy-py)**2
            if dd<best: best=dd
    return math.sqrt(best)
def control(obs):
    try:
        dt=obs.get('dt',0.1) or 0.1
        v=obs['motion']['v_mps'];d=math.radians(obs['steer_deg'])
