        S['th']+=v*math.tan(d)/L*dt
        phi=obs['hitch_deg']
        rig=obs['rig'];hx,hy=rig['hitch'];tr=rig['trailer_rear'];e0=rig['eye']
        mem=S['mem']
        for name,vw in (obs.get('views') or {}).items():
            if not vw: continue
            o=vw.get('origin',[0,0])
            for p in vw.get('walls',[]) or []:
                b=math.radians(p[0]);ds=p[1]
                if ds>6: continue
                wx,wy=tow(o[0]+ds*math.cos(b),o[1]+ds*math.sin(b))
                k=(int(round(wx*10)),int(round(wy*10)))
                if k in mem: del mem[k]
                mem[k]=(wx,wy)
        while len(mem)>1500:
            mem.pop(next(iter(mem)))
        tg=obs.get('target') or {}
        if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None and tg['dist_m']<7:
            b=math.radians(tg['bearing_deg']);dd=tg['dist_m']
            gx,gy=tow(e0[0]+dd*math.cos(b),e0[1]+dd*math.sin(b))
            w=0.03 if dd>4 else 0.06
