        thd_t=rig['trailer_heading_deg'];ht=math.radians(thd_t)
        fx,fy=math.cos(ht),math.sin(ht);nx,ny=-fy,fx;hw=rig['trailer_half_width']+0.02
        fc=(tr[0]+1.0*fx,tr[1]+1.0*fy)
        tcv=[(tr[0]+hw*nx,tr[1]+hw*ny),(tr[0]-hw*nx,tr[1]-hw*ny),(fc[0]+hw*nx,fc[1]+hw*ny),(fc[0]-hw*nx,fc[1]-hw*ny),(tr[0],tr[1])]
