        ax,ay=tow(axv,ayv)
        bdw=wrap(math.degrees(S['th'])+thd_t+180)
        rem=obs['progress']['remaining']
        S['n']+=1
        cyc=S['n']%25
        look=55 if cyc>=19 else clamp(math.degrees(math.atan2(tr[1]-e0[1],tr[0]-e0[0])),-170,170)
        if S['n']%20==0:
            print('t%.1f %s ax(%.2f,%.2f) bdw%.0f phi%.0f t(%.2f,%.2f) dT%.2f dF%.2f rem%.1f nm%d'%(obs['t'],S['mode'],ax,ay,bdw,phi,S['tx'],S['ty'],dT,dF,rem,len(mem)))
