    cam=views.get('camera')
    pts=[]
    if cam:
        ox,oy=cam['origin']
        for w in cam.get('walls',[]):
            b,d=w[0],w[1]
            px=ox+d*math.cos(math.radians(b)); py=oy+d*math.sin(math.radians(b))
            rx,ry=px-tr[0],py-tr[1]
            xt=rx*math.cos(th)+ry*math.sin(th)
            yt=-rx*math.sin(th)+ry*math.cos(th)
            pts.append((xt,yt))
    if cam:
        Ls=[y for x,y in pts if -10<x<-5 and y>1.0]
        Rs=[y for x,y in pts if -10<x<-5 and y<-1.0]
