        if not Rs: Rs=[y for x,y in pts if -14<x<-0.5 and y<-1.0]
        E=[-x for x,y in pts if x<-0.5 and abs(y)<1.0]
        L=med(Ls) if Ls else None
        R=med(Rs) if Rs else None
        lastL,lastR=L,R
        lastE=min(E) if E else None
        if L is not None and R is not None:
            width=L-R
            c=(L+R)/2
        elif L is not None and width:
            c=L-width/2
        elif R is not None and width:
            c=R+width/2
        else:
            c=None
        if c is not None:
            c_f=0.7*c_f+0.3*c
        if lastE is not None and lastE<10 and not woke:
            woke=True
            phase='stop'
            print('END WALL', round(lastE,1), 'L',L,'R',R,'pts',[(round(x,1),round(y,1)) for x,y in pts])
            wake('end wall %.1f m behind trailer'%lastE)
    if t-last_print>4:
        last_print=t
        print('t%.0f h%.1f L%s R%s E%s c%.2f'%(t,hitch,lastL and round(lastL,1),lastR and round(lastR,1),lastE and round(lastE,1),c_f))
    if phase=='stop':
        return (0,0,-41)
    if phase=='rev' and abs(hitch)>40:
        phase='fwd'
    if phase=='fwd':
        if abs(hitch)<5:
            phase='rev'
        else:
            return (clamp(-1.0*hitch,-42,42),1.5,-41)
    alpha=math.degrees(math.atan2(c_f,8.0))
    hd=clamp(2.0*alpha,-25,25)
    steer=clamp(0.38*hitch+1.3*(hitch-hd),-42,42)
    return (steer,-1.5,-41)

