import math
phase='rev'
phi_f=0.0
last_print=-10
tw=False
def clamp(v,a,b):
    return max(a,min(b,v))
def to_tr(px,py,tr,th):
    rx,ry=px-tr[0],py-tr[1]
    return (rx*math.cos(th)+ry*math.sin(th), -rx*math.sin(th)+ry*math.cos(th))
def control(obs):
    global phase,phi_f,last_print,tw
    t=obs['t']
    hitch=obs['hitch_deg']
    rig=obs['rig']
    th=math.radians(rig['trailer_heading_deg'])
    tr=rig['trailer_rear']
    views=obs.get('views') or {}
    cam=views.get('camera')
    tg=obs.get('target') or {}
    aim=None
    if tg.get('in_sight') and tg.get('bearing_deg') is not None:
        ex,ey=rig['eye']
        b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        ax,ay=to_tr(ex+d*math.cos(b),ey+d*math.sin(b),tr,th)
        aim=(ax,ay)
        if not tw:
            tw=True
            print('TARGET seen trailer-frame',round(ax,1),round(ay,1),'tg',tg,'hitch',hitch)
            if cam: print('cam corners',cam.get('target_corners'),'walls',cam.get('walls'))
            wake('target in sight at trailer-frame (%.1f,%.1f)'%(ax,ay))
    if cam:
        ox,oy=cam['origin']
        pts=[]
        for w in cam.get('walls',[]):
            b,d=math.radians(w[0]),w[1]
            pts.append(to_tr(ox+d*math.cos(b),oy+d*math.sin(b),tr,th))
        cands=list(range(-60,61,5))
        fr=[]
        for p in cands:
            ux=-math.cos(math.radians(p)); uy=math.sin(math.radians(p))
            f=15.0
            for x,y in pts:
                s=x*ux+y*uy
                if s<0.5: continue
                if abs(x*uy-y*ux)<2.3: f=min(f,s)
            fr.append(f)
        m=max(fr)
        good=[f>=m-1.0 for f in fr]
        best=None;bi=-1
        i=0
        runs=[]
        while i<len(cands):
            if good[i]:
                j=i
                while j+1<len(cands) and good[j+1]: j+=1
                runs.append((i,j)); i=j+1
