def clamp(v,a,b):
    return max(a,min(b,v))
def to_tr(px,py,tr,th):
    rx,ry=px-tr[0],py-tr[1]
    return (rx*math.cos(th)+ry*math.sin(th), -rx*math.sin(th)+ry*math.cos(th))
def control(obs):
    global phase,phi_f,last_print,tw
    t=obs['t']
    hitch=obs['hitch_deg']
    rig=obs['rig']
    th=math.radians(rig['trailer_heading_deg'])
    tr=rig['trailer_rear']
    views=obs.get('views') or {}
    cam=views.get('camera')
    tg=obs.get('target') or {}
    aim=None
