            last_print=t
            print('t%.0f h%.1f phi%.0f phif%.1f m%.1f aim%s rem%.1f'%(t,hitch,phi,phi_f,m,aim and (round(aim[0],1),round(aim[1],1)),obs['progress']['remaining']))
